Final implementation:

```js
import process from 'node:process';

const FORCE_COLOR_ALIASES = new Set([
  '--color', '--colors', '--colour', '--colours',
]);
const NO_COLOR_ALIASES = new Set([
  '--no-color', '--no-colors', '--no-colour', '--no-colours',
]);

function flagLevel(argv) {
  if (argv.some((arg) => NO_COLOR_ALIASES.has(arg))) return 0;
  if (argv.some((arg) => FORCE_COLOR_ALIASES.has(arg))) return 1;
  return undefined;
}

function envLevel(env) {
  const forceColor = env.FORCE_COLOR;
  if (forceColor !== undefined) {
    if (forceColor === '' || forceColor === 'true') return 1;
    if (forceColor === 'false') return 0;
    const level = Number.parseInt(forceColor, 10);
    return Number.isNaN(level) ? 1 : Math.min(Math.max(level, 0), 3);
  }
  if (env.NO_COLOR !== undefined && env.NO_COLOR !== '') return 0;
  return undefined;
}

function streamLevel(stream, env) {
  if (!stream || !stream.isTTY) return 0;
  if (env.TERM === 'dumb') return 0;
  if (process.platform === 'win32') {
    // Modern Windows terminals support VT sequences; Node enables them for
    // stdout when it is a TTY.
    if (env.CI) return 1;
    return 1;
  }
  if (/truecolor|24bit/i.test(env.COLORTERM || '')) return 3;
  if (/256color/i.test(env.TERM || '')) return 2;
  return 1;
}

export function detectColorLevel(stream = process.stdout, env = process.env, argv = process.argv.slice(2)) {
  return flagLevel(argv) ?? envLevel(env) ?? streamLevel(stream, env);
}

export const supportsColor = {
  stdout: detectColorLevel(process.stdout),
  stderr: detectColorLevel(process.stderr),
};
```

