{
  "name": "color-cli",
  "version": "1.0.0",
  "description": "Node.js CLI that detects terminal color support before printing colored output.",
  "type": "module",
  "bin": {
    "color-cli": "./bin/cli.js"
  },
  "exports": "./src/supports-color.js",
  "files": [
    "bin",
    "src"
  ],
  "scripts": {
    "start": "node bin/cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

import process from 'node:process';

const COLOR_FLAGS = new Set(['--color', '--colors', '--colour', '--colours']);
const NO_COLOR_FLAGS = new Set([
  '--no-color',
  '--no-colors',
  '--no-colour',
  '--no-colours',
]);

function levelFromFlags(argv) {
  if (argv.some((arg) => NO_COLOR_FLAGS.has(arg))) return 0;
  if (argv.some((arg) => COLOR_FLAGS.has(arg))) return 1;
  return undefined;
}

function levelFromEnv(env) {
  const forced = env.FORCE_COLOR;
  if (forced !== undefined) {
    if (forced === '' || forced === 'true') return 1;
    if (forced === 'false') return 0;
    const parsed = Number.parseInt(forced, 10);
    return Number.isNaN(parsed) ? 1 : Math.min(Math.max(parsed, 0), 3);
  }

  if (env.NO_COLOR !== undefined && env.NO_COLOR !== '') return 0;

  return undefined;
}

function levelFromStream(stream, env) {
  if (!stream || !stream.isTTY) return 0;
  if (env.TERM === 'dumb') return 0;

  if (process.platform === 'win32') {
    if (env.CI) return 1;
    if (env.WT_SESSION || env.ANSICON || env.TERM_PROGRAM === 'vscode') return 3;
    return 1;
  }

  if (/truecolor|24bit/i.test(env.COLORTERM || '')) return 3;
  if (/256color/i.test(env.TERM || '')) return 2;
  return 1;
}

/**
 * Returns the color support level for a stream:
 *   0 = none, 1 = 16 colors, 2 = 256 colors, 3 = truecolor.
 */
export function detectColorLevel(
  stream = process.stdout,
  env = process.env,
  argv = process.argv.slice(2),
) {
  return levelFromFlags(argv) ?? levelFromEnv(env) ?? levelFromStream(stream, env);
}

export const supportsColor = {
  stdout: detectColorLevel(process.stdout),
  stderr: detectColorLevel(process.stderr),
};

#!/usr/bin/env node
import { detectColorLevel } from '../src/supports-color.js';

const level = detectColorLevel();

const paint = {
  0: (text) => text,
  1: (text) => `\x1b[31m${text}\x1b[39m`,
  2: (text) => `\x1b[38;5;196m${text}\x1b[39m`,
  3: (text) => `\x1b[38;2;255;0;0m${text}\x1b[39m`,
}[level];

const summary = {
  0: 'none',
  1: '16 colors',
  2: '256 colors',
  3: 'truecolor',
}[level];

console.log(paint('Hello, colored world!'));
console.log(`Detected color support: level ${level} (${summary})`);

import test from 'node:test';
import assert from 'node:assert/strict';
import { detectColorLevel } from '../src/supports-color.js';

const tty = { isTTY: true };
const pipe = { isTTY: false };

test('returns 0 when the stream is not a TTY', () => {
  assert.equal(detectColorLevel(pipe, { TERM: 'xterm-256color' }, []), 0);
});

test('NO_COLOR disables color even on a TTY', () => {
  assert.equal(detectColorLevel(tty, { NO_COLOR: '1', TERM: 'xterm-256color' }, []), 0);
});

test('--no-color flag disables color', () => {
  assert.equal(detectColorLevel(tty, { TERM: 'xterm-256color' }, ['--no-color']), 0);
});

test('FORCE_COLOR overrides a non-TTY stream', () => {
  assert.equal(detectColorLevel(pipe, { FORCE_COLOR: '3' }, []), 3);
});

test('--color flag enables color for a non-TTY stream', () => {
  assert.equal(detectColorLevel(pipe, {}, ['--color']), 1);
});

test('TERM=256color yields level 2', () => {
  assert.equal(detectColorLevel(tty, { TERM: 'xterm-256color' }, []), 2);
});

test('COLORTERM=truecolor yields level 3', () => {
  assert.equal(detectColorLevel(tty, { COLORTERM: 'truecolor' }, []), 3);
});

test('TERM=dumb disables color', () => {
  assert.equal(detectColorLevel(tty, { TERM: 'dumb' }, []), 0);
});

test('flat TTY yields level 1', () => {
  assert.equal(detectColorLevel(tty, { TERM: 'xterm' }, []), 1);
});
